#include "SSAO.h"
#include <random>
SSAO::SSAO(int W,int H):w(W),h(H){std::mt19937 g(7);std::uniform_real_distribution<float>d(0,1);for(int i=0;i<32;i++){Vec3 s=normalize({d(g)*2-1,d(g)*2-1,d(g)});s=s*d(g);float t=(float)i/32.0f;float scale=.1f+.9f*t*t;kernel.push_back(s*scale);}Vec3 ns[16];for(auto&n:ns)n={d(g)*2-1,d(g)*2-1,0};glGenTextures(1,&noise);glBindTexture(GL_TEXTURE_2D,noise);glTexImage2D(GL_TEXTURE_2D,0,GL_RGB16F,4,4,0,GL_RGB,GL_FLOAT,ns);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_R16F,w,h,0,GL_RED,GL_FLOAT,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,texture,0);glBindFramebuffer(GL_FRAMEBUFFER,0);}
SSAO::~SSAO(){glDeleteTextures(1,&noise);glDeleteTextures(1,&texture);glDeleteFramebuffers(1,&fbo);}

